    analyzeBatchFiles() {
      // 检查文件数量是否为偶数
      if (this.batchFileList.length % 2 !== 0) {
        this.$message.warning("上传图片数量为奇数，最后一张图片将不会被处理");
      }

      // 计算能处理的图片对数量
      const pairCount = Math.floor(this.batchFileList.length / 2);

      // 检查图片对数量与选择的患者数量关系
      if (this.selectedPatientIds.length > 0) {
        if (pairCount < this.selectedPatientIds.length) {
          this.$message.warning(`图片对数量(${pairCount})少于患者数量(${this.selectedPatientIds.length})，多余的患者将不会被处理`);
        } else if (pairCount > this.selectedPatientIds.length) {
          this.$message.warning(`图片对数量(${pairCount})多于患者数量(${this.selectedPatientIds.length})，多余的图片对将不会被处理`);
        }
      }

      // 按顺序配对图片（只处理偶数张）
      this.pairedImages = [];
      const evenCount = Math.floor(this.batchFileList.length / 2) * 2;
      for (let i = 0; i < evenCount; i += 2) {
        this.pairedImages.push({
          leftEye: this.batchFileList[i],
          rightEye: this.batchFileList[i + 1]
        });
      }

      // 记录未配对的图片
      this.unpairedImages = this.batchFileList.length % 2 !== 0 ? [this.batchFileList[this.batchFileList.length - 1]] : [];
    },
    async processBatchImages() {
      if (this.selectedPatientIds.length === 0) {
        this.$message.warning("请先选择患者");
        return;
      }

      // 确保图片对数不为零
      if (this.pairedImages.length === 0) {
        this.$message.warning("请上传至少一对图片（左右眼）");
        return;
      }

      // 计算实际可处理的患者数量和图片对数量
      const actualPatientCount = Math.min(this.selectedPatientIds.length, this.pairedImages.length);
      const actualPairCount = Math.min(this.selectedPatientIds.length, this.pairedImages.length);

      // 根据实际处理数量裁剪患者ID和图片对
      const processPatientIds = this.selectedPatientIds.slice(0, actualPatientCount);
      const processPairs = this.pairedImages.slice(0, actualPairCount);
      this.processingMode = "batch";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      this.processedCount = 0;
      this.totalProcessCount = actualPairCount;
      try {
        // 准备批量上传的数据
        const uploadPromises = [];
        const imagePaths = [];

        // 上传所有要处理的图片
        for (const pair of processPairs) {
          const leftFormData = new FormData();
          const rightFormData = new FormData();
          leftFormData.append("file", pair.leftEye.raw);
          rightFormData.append("file", pair.rightEye.raw);
          uploadPromises.push(request({
            method: "post",
            url: "/common/upload",
            data: leftFormData,
            headers: {
              "Content-Type": "multipart/form-data"
            }
          }));
          uploadPromises.push(request({
            method: "post",
            url: "/common/upload",
            data: rightFormData,
            headers: {
              "Content-Type": "multipart/form-data"
            }
          }));
        }

        // 等待所有图片上传完成
        const uploadResults = await Promise.all(uploadPromises);

        // 收集所有上传成功的图片路径
        uploadResults.forEach(response => {
          if (response.code === 1) {
            imagePaths.push(response.data);
          }
        });
        if (imagePaths.length === processPairs.length * 2) {
          // 准备批量诊断请求数据
          const doctorId = localStorage.getItem("doctorId");
          const diagnosisData = {
            patientIds: processPatientIds,
            doctorId: parseInt(doctorId),
            imagePaths: imagePaths
          };

          // 调用批量诊断API
          const diagnosisResponse = await request({
            method: "post",
            url: "/diagnose/batch",
            data: diagnosisData
          });
          if (diagnosisResponse.code === 1) {
            // 处理诊断结果
            this.processBatchResults(diagnosisResponse.data);
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.showResults = true;
            }, 500);
          } else {
            throw new Error(diagnosisResponse.msg || "批量诊断失败");
          }
        } else {
          throw new Error("部分图片上传失败");
        }
      } catch (error) {
        console.error("批量处理错误:", error);
        this.$message.error(error.message || "批量处理失败，请稍后重试");
        this.processingDialogVisible = false;
      }
    },
    processBatchResults(results) {
      this.batchResults = results.map(result => ({
