            const result = diagnosisResponse.data;

            // 更新诊断结果
            this.singleResult = {
              leftEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseLeft.labels),
                confidence: Math.max(...result.diseaseLeft.probabilities) * 100,
                probabilities: result.diseaseLeft.probabilities
              },
              rightEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseRight.labels),
                confidence: Math.max(...result.diseaseRight.probabilities) * 100,
                probabilities: result.diseaseRight.probabilities
              },
              finalDiagnosis: result.finalResult,
              suggestion: this.generateSuggestion(this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseLeft.labels)), this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseRight.labels)))
            };

            // 更新患者诊断信息
            const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
            if (patientIndex !== -1) {
              const patient = this.patientList[patientIndex];
              patient.leftEyeDiagnosis = result.leftResult; // 使用API返回的左眼结果
              patient.rightEyeDiagnosis = result.rightResult; // 使用API返回的右眼结果
              patient.finalDiagnosis = result.finalResult; // 使用API返回的最终结果
              patient.leftEyeConfidence = Math.max(...result.diseaseLeft.probabilities) * 100;
              patient.rightEyeConfidence = Math.max(...result.diseaseRight.probabilities) * 100;
              patient.processTime = new Date().toLocaleString();

              // this.$set(this.patientList, patientIndex, patient);
              // Use direct assignment for Vue 3 reactivity
              this.patientList[patientIndex] = patient;
            }

            // 更新进度并显示结果
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.updatePatientDiagnosis();
              this.showResults = true;

              // 添加到历史记录
              this.addToHistory(this.singleResult);

              // 渲染图表
              this.$nextTick(() => {
                this.renderEyeChart("leftEyeChart", this.singleResult.leftEye.probabilities);
                this.renderEyeChart("rightEyeChart", this.singleResult.rightEye.probabilities);
                this.renderComparisonChart(this.singleResult.leftEye.probabilities, this.singleResult.rightEye.probabilities);
              });
            }, 500);
          } else {
            throw new Error(diagnosisResponse.msg || "诊断失败");
          }
        } else {
          throw new Error("文件上传失败");
        }
      } catch (error) {
        console.error("处理图像错误:", error);
        this.$message.error(error.message || "图像处理失败，请稍后重试");
        this.processingDialogVisible = false;
      }
    },
    // 根据标签数组获取诊断结果
    getDiagnosisFromLabels(labels) {
      // 根据返回的标签数组中最可能的标签确定诊断结果
      if (labels && labels.length > 0) {
        const label = labels[0]; // 取第一个最可能的标签
        switch (label) {
          case "A":
            return "糖尿病视网膜病变";
          case "G":
            return "青光眼";
          case "C":
            return "白内障";
          case "H":
            return "高血压视网膜病变";
          case "M":
            return "近视";
          case "O":
            return "其他异常";
          case "N":
            return "正常";
          default:
            return "未知";
        }
      }
      return "未知";
    },
    updatePatientDiagnosis() {
      // 更新患者诊断信息
      if (this.selectedPatientId && this.singleResult) {
        const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
        if (patientIndex !== -1) {
          const patient = this.patientList[patientIndex];
          const now = new Date();
          patient.leftEyeDiagnosis = this.singleResult.leftEye.diagnosis;
          patient.leftEyeConfidence = this.singleResult.leftEye.confidence;
          patient.rightEyeDiagnosis = this.singleResult.rightEye.diagnosis;
          patient.rightEyeConfidence = this.singleResult.rightEye.confidence;
          patient.finalDiagnosis = this.singleResult.finalDiagnosis;
          patient.processTime = now.toLocaleString();

          // this.$set(this.patientList, patientIndex, patient);
          // Use direct assignment for Vue 3 reactivity
          this.patientList[patientIndex] = patient;
        }
      }
    },
    // 渲染左右眼比较柱状图
    renderComparisonChart(leftEyeProbs, rightEyeProbs) {
      const chartDom = this.$refs.comparisonChart;
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const disease = this.diseaseCategories[params[0].dataIndex];
            let result = `${disease}<br/>`;
            params.forEach(param => {
              const value = param.value;
              result += `${param.seriesName}: ${value}%<br/>`;
            });
            return result;
          }
        },
        legend: {
          data: ["左眼", "右眼"]
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: this.diseaseCategories
        },
        yAxis: {
          type: "value",
          name: "概率 (%)",
          max: 100
        },
        series: [{
          name: "左眼",
          type: "bar",
          data: leftEyeProbs.map(p => (p * 100).toFixed(1)),
          itemStyle: {
            color: "#409EFF"
          }
        }, {
          name: "右眼",
          type: "bar",
          data: rightEyeProbs.map(p => (p * 100).toFixed(1)),
          itemStyle: {
            color: "#FF6B6B"
          }
        }]
      };
      myChart.setOption(option);

      // 响应窗口大小变化
      window.addEventListener("resize", function () {
        myChart.resize();
      });
    },
    // 渲染单眼图表
    renderEyeChart(chartId, probabilities) {
      const chartDom = this.$refs[chartId];
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const dataIndex = params[0].dataIndex;
            const value = params[0].value;
            return `${this.diseaseCategories[dataIndex]}: ${value}%`;
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: this.diseaseCategories.map(cat => cat.substring(0, 4) + "..."),
          axisLabel: {
            interval: 0,
            rotate: 45
          }
        },
        yAxis: {
          type: "value",
          axisLabel: {
            formatter: "{value}%"
          },
          max: 100
        },
        series: [{
          name: "概率",
          type: "bar",
          data: probabilities.map(p => (p * 100).toFixed(2)),
          itemStyle: {
            color: function (params) {
              const colorList = ["#FF5252",
              // 糖尿病
              "#7C4DFF",
              // 青光眼
              "#448AFF",
              // 白内障
              "#FFC107",
              // AMD
              "#FF9800",
              // 高血压
              "#00BCD4",
              // 近视
              "#9C27B0",
              // 其他异常
              "#4CAF50" // 正常
              ];
              return colorList[params.dataIndex];
            }
          }
        }]
      };
      myChart.setOption(option);

      // 响应窗口大小变化
      window.addEventListener("resize", function () {
        myChart.resize();
      });
    },
    // 生成建议
    generateSuggestion(leftIndex, rightIndex) {
      // 根据诊断结果生成建议
      const suggestions = {
        0: "建议进行血糖控制，定期复查眼底，必要时考虑激光或抗VEGF治疗。",
        1: "建议测量眼压，进行视野检查，必要时使用降眼压药物。",
        2: "建议进行视力矫正，必要时考虑白内障手术。",
        3: "建议定期监测黄斑区变化，必要时考虑抗VEGF治疗。",
        4: "建议控制血压，定期复查眼底。",
        5: "建议进行屈光矫正，控制近距离用眼时间。",
        6: "建议进一步检查确定具体异常类型。",
        7: "眼底未见明显异常，建议定期检查。"
      };
      if (leftIndex === rightIndex) {
        return suggestions[leftIndex];
      } else {
        return `左眼：${suggestions[leftIndex]}\n右眼：${suggestions[rightIndex]}`;
      }
    },
    // 报告操作
    saveReport() {
      this.$message.success("报告已保存到系统");
    },
    exportReport() {
      this.$message.success("报告已导出为PDF文件");
    },
    viewBatchDetail(row) {
      // 查看批量诊断中的单个详情
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportBatchReport(row) {
      this.$message.success(`ID ${row.id} 的报告已导出为PDF文件`);
    },
    saveAllBatchReports() {
      this.$message.success(`已保存全部 ${this.batchResults.length} 份报告`);
    },
    exportAllBatchReports() {
      this.$message.success(`已导出全部 ${this.batchResults.length} 份报告为PDF文件`);
    },
    // 历史记录操作
    addToHistory(result) {
      const now = new Date();
      const timeStr = now.toLocaleString();
      this.historyRecords.unshift({
        ...result,
        time: timeStr
      });
    },
    viewHistoryDetail(row) {
      this.$router.push(`/reports/detail/${row.patientId}`);
    },
    exportHistoryReport(row) {
      this.$message.success(`历史记录 ID ${row.id} 的报告已导出为PDF文件`);
    },
    getTaskStatusText(status) {
      switch (status) {
        case "waiting":
          return "等待中";
        case "processing":
          return "处理中";
        case "completed":
          return "已完成";
        default:
          return "未知状态";
      }
    },
    percentageFormat(percentage) {
      return percentage + "%";
    },
    // 获取患者列表
    async fetchPatientList() {
      // 先尝试从 localStorage 读取
      const hasLocalData = this.loadPatientListFromLocalStorage();

      // 如果本地没有数据，再从服务器获取
      if (!hasLocalData) {
        try {
          const response = await request({
            method: "get",
            url: "/patients/pageNow",
            params: {
              page: 1,
              pageSize: 10
            }
          });
          if (response.code === 200 || response.code === 1) {
            // 将后端返回的患者数据转换为前端需要的格式
            this.patientList = response.data.records.map(patient => ({
              id: patient.patientId,
              // 从patientId映射到id
              name: patient.name,
              gender: patient.gender,
              age: patient.age,
              phone: patient.phoneNumber || "",
              // 如果API返回了phoneNumber字段
              note: patient.remarks || "",
              // 如果API返回了remarks字段
              leftEyeDiagnosis: patient.leftResult || "",
              rightEyeDiagnosis: patient.rightResult || "",
              leftEyeConfidence: 0,
              // 后端暂无此字段
              rightEyeConfidence: 0,
              // 后端暂无此字段
              finalDiagnosis: patient.finalResult || "",
              processTime: patient.diagnosisTime || ""
            }));

            // 保存到 localStorage
            this.savePatientListToLocalStorage();
          } else {
            this.$message.error(response.msg || "获取患者列表失败");
          }
        } catch (error) {
          console.error("获取患者列表错误:", error);
          this.$message.error("获取患者列表失败，请稍后重试");
        }
      }
    },
    // 历史记录操作
    async fetchHistoryRecords() {
      this.historyLoading = true;
      try {
        const response = await request({
          method: "get",
          url: "/patients/pageHistory",
          params: {
            page: this.historyCurrentPage,
            pageSize: this.historyPageSize,
            name: this.historySearchName || undefined
          }
        });
        if (response.code === 0 || response.code === 1) {
          // 将API返回的数据直接赋值给历史记录，确保字段映射正确
          this.historyRecords = response.data.records.map(record => ({
            id: record.patientId,
            patientId: record.patientId,
            patientName: record.name,
            diagnosisTime: record.diagnosisTime,
            leftEye: record.leftResult || "",
            rightEye: record.rightResult || "",
            comprehensiveDiagnosis: record.finalResult || ""
          }));

          // 更新总条数
          this.historyTotal = response.data.total;
        } else {
          this.$message.error(response.msg || "获取历史记录失败");
        }
      } catch (error) {
        console.error("获取历史记录错误:", error);
        this.$message.error("获取历史记录失败，请稍后重试");
      } finally {
        this.historyLoading = false;
      }
    },
    // 按姓名搜索历史记录
    searchHistoryByName() {
      this.historyCurrentPage = 1;
      this.fetchHistoryRecords();
    },
    // 重置历史记录搜索
    resetHistorySearch() {
      this.historySearchName = "";
      this.historyCurrentPage = 1;
      this.fetchHistoryRecords();
    },
    // 处理历史记录分页变化
    handleHistoryPageChange(page) {
      this.historyCurrentPage = page;
      this.fetchHistoryRecords();
    },
    // 计算文件大小的格式化方法
    formatFileSize(row, column, cellValue) {
      const size = row.size;
      if (size < 1024) {
        return size + " B";
      } else if (size < 1024 * 1024) {
        return (size / 1024).toFixed(1) + " KB";
      } else {
        return (size / (1024 * 1024)).toFixed(1) + " MB";
      }
    },
    // 判断文件是否已配对
    isFilePaired(file) {
      const pairedFiles = this.pairedImages.flatMap(pair => [pair.leftEye, pair.rightEye]);
      return pairedFiles.some(pairedFile => pairedFile.uid === file.uid);
    },
    // 保存患者列表到 localStorage
    savePatientListToLocalStorage() {
      localStorage.setItem("patientList", JSON.stringify(this.patientList));
    },
    // 从 localStorage 读取患者列表
    loadPatientListFromLocalStorage() {
      const savedPatientList = localStorage.getItem("patientList");
      if (savedPatientList) {
        this.patientList = JSON.parse(savedPatientList);
        return true;
      }
      return false;
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 获取患者列表
    this.fetchPatientList();

    // 获取历史诊断记录
    this.fetchHistoryRecords();
  }
};
